187	/// Helper function to insert instructions into the current function's data flow graph.
188	fn insert_local_instructions<T>(
189	    program: &mut Program,
190	    my_ir_generator_info: &mut MyIRGeneratorInfo,
191	    instructions: T,
192	) where
193	    T: IntoIterator<Item = Value>,
194	{
195	    program
196	        .func_mut(my_ir_generator_info.curr_func.unwrap())
197	        .layout_mut()
198	        .bb_mut(my_ir_generator_info.curr_block.unwrap())
199	        .insts_mut()
200	        .extend(instructions);
201	}
202	
203	/// Helper function to insert basic blocks into the current function's data flow graph.
204	fn insert_basic_blocks<T>(
205	    program: &mut Program,
206	    my_ir_generator_info: &mut MyIRGeneratorInfo,
207	    basic_blocks: T,
208	) where
209	    T: IntoIterator<Item = BasicBlock>,
210	{
211	    program
212	        .func_mut(my_ir_generator_info.curr_func.unwrap())
213	        .layout_mut()
214	        .bbs_mut()
215	        .extend(basic_blocks);
216	}
