fn flatten_init(shape: &[usize], childs: &[InitVal], out: &mut Vec<Elem>, ...) {
    let total = product(shape);
    let start_len = out.len();
    if shape.len() == 1 {
        for child in childs {
            match child {
                Exp(e) => push eval(e),
                Aggregate(gc) => for c in gc: push eval(c as exp...) // braces around scalars
            }
        }
        pad to total with 0
    } else {
        let sub_size = product(shape[1..]);
        let mut filled = 0; // scalars filled at this level
        for child in childs {
            match child {
                Aggregate(gc) => {
                    // align filled up to multiple of sub_size
                    while filled % sub_size != 0 { push 0; filled += 1; }
                    flatten_init(&shape[1..], gc, out, ...);
                    filled += sub_size;
                }
                Exp(e) => { push eval(e); filled += 1; }
            }
        }
        pad zeros to total
    }
}
