fn flatten_aggregate(
    shape: &[usize],
    childs: &[Box<InitVal>],
    is_global: bool,
    program: &mut Program,
    info: &mut MyIRGeneratorInfo,
    out: &mut Vec<FlatElem>,
) -> Result<(), String> {
    let total = product_of(shape);
    let mut filled = 0usize;
    if shape.len() <= 1 {
        for child in childs {
            match &**child {
                InitVal::Exp(exp) => {
                    out.push(eval_init_exp(exp, is_global, program, info)?);
                    filled += 1;
                }
                // Braces around scalar elements: fill sequentially.
                InitVal::Aggregate(grand_childs) => {
                    flatten_aggregate(shape, grand_childs, is_global, program, info, out)?;
                    filled = out.len(); // hmm
