                InitVal::Exp(exp) => {
                    out.push(eval_init_exp(exp, is_global, program, info)?);
                    filled += 1;
                }
            }
        }
    }
    if filled > total {
        return Err("Too many elements in aggregate initializer".into());
    }
    while filled < total {
        out.push(FlatElem::Const(0));
        filled += 1;
    }
    Ok(())
}
