fn build_aggregate_tree(
    shape: &[usize],
    flat: &[FlatElem],
    cursor: &mut usize,
    flat_base: usize,
    program: &mut Program,
    dyn_elems: &mut Vec<(usize, Value)>,
) -> Result<Value, String> {
    if shape.len() <= 1 {
        let n = if shape.is_empty() { 1 } else { shape[0] };
        let mut elems = Vec::with_capacity(n);
        for _ in 0..n {
            let idx = flat_base + *cursor;
            match &flat[*cursor] {
                FlatElem::Const(c) => elems.push(program.new_value().integer(*c)),
                FlatElem::Dyn(v) => {
                    elems.push(program.new_value().integer(0));
                    dyn_elems.push((idx, *v));
                }
            }
            *cursor += 1;
        }
        if shape.is_empty() {
            Ok(elems.pop().unwrap())
        } else {
            Ok(program.new_value().aggregate(elems))
        }
    } else {
        let mut elems = Vec::with_capacity(shape[0]);
        for i in 0..shape[0] {
            elems.push(build_aggregate_tree(&shape[1..], flat, cursor, flat_base + i * product_of(&shape[1..]), program, dyn_elems)?);
        }
        Ok(program.new_value().aggregate(elems))
    }
}
