fn aggregate_to_store_insts(
    aggr: Value,
    aggr_ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    let data = get_valuedata(aggr, program, my_ir_generator_info);
