/// Build the Koopa value(s) for a variable definition and insert the symbol
/// into the current symbol table. Shared by `VarDecl` and array `ConstDecl`.
fn build_var_def(
    btype: &BType,
    ident: &str,
    shape: &[usize],
    init_val: Option<&InitVal>,
    program: &mut Program,
    info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    if info.symbol_tables.symbol_tables.last().unwrap().contains_key(ident) {
        return Err(format!("Duplicate symbol definition: {}", ident));
    }
    let is_global = info.curr_func.is_none();
    let type_kind = get_array_type(btype, shape);
    let ty = Type::get(type_kind.clone());
    if shape.is_empty() {
        // Scalar.
        if is_global {
            let init = match init_val {
                None => program.new_value().zero_init(ty),
                Some(iv) => match iv.build(shape, program, info)? {
                    IRInitValBuildResult::Const(c) => program.new_value().integer(c),
                    IRInitValBuildResult::Aggregate(v) => program.new_value().integer(const_int_from_value(v, program, info)?),
                    _ => return Err(...),
                },
            };
            let ptr = program.new_value().global_alloc(init);
            info.symbol_tables.insert(ident.to_string(), SymbolTableEntry::Variable(type_kind, ptr));
        } else {
            let alloc = create_new_local_value(program, info).alloc(ty);
            let mut insts = vec![alloc];
            if let Some(iv) = init_val {
                let value = match iv.build(shape, program, info)? {
                    IRInitValBuildResult::Const(c) => create_new_local_value(program, info).integer(c),
                    IRInitValBuildResult::Var(v) => v,
                    IRInitValBuildResult::Aggregate(v) => { let c = const_int_from_value(v, program, info)?; create_new_local_value(program, info).integer(c) }
                    IRInitValBuildResult::AggregateWithDyn(_, dyns) => {
                        // scalar: single dynamic element at flat index 0
                        match dyns.iter().find(|(i, _)| *i == 0) { Some((_, v)) => *v, None => return Err(...) }
                    }
                };
                let store = create_new_local_value(program, info).store(value, alloc);
                insts.push(store);
            }
            insert_local_instructions(program, info, insts);
            info.symbol_tables.insert(...);
        }
    } else {
        // Array.
        if is_global {
            let init = match init_val {
                None => program.new_value().zero_init(ty),
                Some(iv) => match iv.build(shape, program, info)? {
                    IRInitValBuildResult::Aggregate(v) => v,
                    _ => return Err("Array initializer must be an aggregate"),
                },
            };
            let ptr = program.new_value().global_alloc(init);
            insert symbol;
        } else {
            let alloc = create_new_local_value(program, info).alloc(ty);
            insert_local_instructions(program, info, [alloc]);
            if let Some(iv) = init_val {
                match iv.build(shape, program, info)? {
                    IRInitValBuildResult::Aggregate(v) => aggregate_to_store_insts(v, alloc, program, info)?,
                    IRInitValBuildResult::AggregateWithDyn(v, dyns) => {
                        aggregate_to_store_insts(v, alloc, program, info)?;
                        emit_dyn_stores(shape, &dyns, alloc, program, info)?;
                    }
                    _ => return Err(...),
                }
            }
            insert symbol;
        }
    }
    Ok(())
}
