```rust
/// Emit per-element stores for dynamic elements of a local array initializer.
fn emit_dyn_stores(
    shape: &[usize],
    dyn_elems: &[(usize, Value)],
    alloc: Value,
    program: &mut Program,
    info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    for (flat_index, value) in dyn_elems {
        // Decompose the flat index into per-dimension indices (row-major).
        let mut indices = Vec::with_capacity(shape.len());
        let mut rest = *flat_index;
        for i in 0..shape.len() {
            let stride: usize = shape[i + 1..].iter().product();
            indices.push(rest / stride);
            rest %= stride;
        }
        let mut ptr = alloc;
        for idx in indices {
            let index_value = create_new_local_value(program, info).integer(idx as i32);
            let gep = create_new_local_value(program, info).get_elem_ptr(ptr, index_value);
            insert_local_instructions(program, info, [index_value, gep]);
            ptr = gep;
        }
        let store = create_new_local_value(program, info).store(*value, ptr);
        insert_local_instructions(program, info, [store]);
    }
    Ok(())
}
```

