//! Build a single component into Koopa IR.

use crate::ast_def::declarations::*;
use crate::ast_def::symbols::BType;
use koopa::ir::{builder_traits::*, FunctionData, Program, Type, TypeKind, Value, ValueKind};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable},
    build_shape, create_new_block, create_new_local_value, get_array_type, get_valuedata,
    insert_basic_blocks, insert_local_instructions, IRBuildResult, IRBuildable, MyIRGeneratorInfo,
    SymbolTableEntry,
};

impl IRBuildable for FuncDef {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let FuncDef::Default(btype, ident, params, block) = self;
        if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
            return Err(format!("Duplicate global symbol: {}", ident.content));
        }
        let ret_type = match btype.content {
            TypeKind::Int32 => Type::get_i32(),
            _ => Type::get_unit(),
        };
        // Build parameter types. Scalar params are i32; array params `int a[][d2][d3]...`
        // become pointers to the array of the remaining dimensions.
        let mut param_names_with_types = Vec::with_capacity(params.len());
        let mut param_typekinds = Vec::with_capacity(params.len());
        for FuncFParam::Default(param_btype, param_ident, dims) in params {
            let type_kind = match dims {
                None => TypeKind::Int32,
                Some(shape_exps) => {
                    let dims = build_shape(shape_exps, program, my_ir_generator_info)?;
                    TypeKind::Pointer(Type::get(get_array_type(param_btype, &dims)))
                }
            };
            param_names_with_types
                .push((Some(format!("@{}", param_ident.content)), Type::get(type_kind.clone())));
            param_typekinds.push(type_kind);
        }
        let func_data = FunctionData::with_param_names(
            format!("@{}", ident.content),
            param_names_with_types,
            ret_type,
        );
        let func = program.new_func(func_data);
        my_ir_generator_info
            .function_table
            .insert(ident.content.clone(), func);
        my_ir_generator_info.curr_func = Some(func);
        // Create the entry block.
        let entry = create_new_block(program, my_ir_generator_info, "entry");
        insert_basic_blocks(program, my_ir_generator_info, [entry]);
        my_ir_generator_info.curr_block = Some(entry);
        // New scope for the parameters. Popped by Block::build.
        my_ir_generator_info.symbol_tables.add_new_table();
        // Store each parameter into a local alloc slot. Array parameters are
        // slots holding a pointer, i.e. the pointee type is itself a pointer.
        for (i, (FuncFParam::Default(_, param_ident, _), type_kind)) in params
            .iter()
            .zip(param_typekinds.iter())
            .enumerate()
        {
            let param_value = program.func(func).params()[i];
            let alloc =
                create_new_local_value(program, my_ir_generator_info).alloc(Type::get(type_kind.clone()));
            let store = create_new_local_value(program, my_ir_generator_info).store(param_value, alloc);
            insert_local_instructions(program, my_ir_generator_info, [alloc, store]);
            my_ir_generator_info.symbol_tables.insert(
                param_ident.content.clone(),
                SymbolTableEntry::Variable(type_kind.clone(), alloc),
            );
        }
        // Build the function body.
        let result = block.build(program, my_ir_generator_info)?;
        // If the body does not end with a terminator, append a default return.
        if !matches!(result, IRBuildResult::EARLYSTOPPING) {
            match btype.content {
                TypeKind::Int32 => {
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let ret = create_new_local_value(program, my_ir_generator_info).ret(Some(zero));
                    insert_local_instructions(program, my_ir_generator_info, [zero, ret]);
                }
                _ => {
                    let ret = create_new_local_value(program, my_ir_generator_info).ret(None);
                    insert_local_instructions(program, my_ir_generator_info, [ret]);
                }
            }
        }
        my_ir_generator_info.curr_func = None;
        my_ir_generator_info.curr_block = None;
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for Block {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let Block::Default(stmts) = self;
        let mut block_result = IRBuildResult::OK;
        for stmt in stmts {
            let result = stmt.build(program, my_ir_generator_info)?;
            // Ignore everything after the return statement.
            if let IRBuildResult::EARLYSTOPPING = result {
                block_result = result;
                break;
            }
        }
        my_ir_generator_info.symbol_tables.delete_new_table();
        Ok(block_result)
    }
}

impl IRBuildable for BlockItem {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BlockItem::Decl(decl) => decl.build(program, my_ir_generator_info),
            BlockItem::Stmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

pub enum IRInitValBuildResult {
    Const(i32),
    Var(Value),
    Aggregate(Value),
    /// A constant aggregate value plus dynamic elements (flattened index and
    /// value) that still need per-element stores. Only produced for local
    /// initializers, where initializer expressions may be non-constant.
    AggregateWithDyn(Value, Vec<(usize, Value)>),
}

/// A single flattened scalar element of an aggregate initializer.
enum FlatElem {
    Const(i32),
    Dyn(Value),
}

fn product_of(shape: &[usize]) -> usize {
    shape.iter().product()
}

/// Evaluate a scalar initializer expression. Non-constant expressions are only
/// allowed in local initializers.
fn eval_init_exp(
    exp: &crate::ast_def::expressions::Exp,
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<FlatElem, String> {
    match exp.build(program, my_ir_generator_info)? {
        IRExpBuildResult::Const(int) => Ok(FlatElem::Const(int)),
        IRExpBuildResult::Value(value) => {
            if is_global {
                Err(format!(
                    "Non-constant expression '{:?}' in global aggregate initval",
                    exp
                ))
            } else {
                Ok(FlatElem::Dyn(value))
            }
        }
    }
}

/// Flatten an aggregate initializer into a row-major list of scalar elements,
/// following C brace elision rules. Missing elements are padded with 0.
fn flatten_aggregate(
    shape: &[usize],
    childs: &[Box<InitVal>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    out: &mut Vec<FlatElem>,
) -> Result<(), String> {
    let total = product_of(shape);
    let mut filled = 0usize;
    if shape.len() <= 1 {
        for child in childs {
            match &**child {
                InitVal::Exp(exp) => {
                    out.push(eval_init_exp(exp, is_global, program, my_ir_generator_info)?);
                    filled += 1;
                }
                // Braces around scalar elements: fill sequentially.
                InitVal::Aggregate(grand_childs) => {
                    for grand_child in grand_childs {
                        match &**grand_child {
                            InitVal::Exp(exp) => {
                                out.push(eval_init_exp(
                                    exp,
                                    is_global,
                                    program,
                                    my_ir_generator_info,
                                )?);
                                filled += 1;
                            }
                            InitVal::Aggregate(_) => {
                                return Err("Aggregate initializer nesting too deep".to_string())
                            }
                        }
                    }
                }
            }
        }
    } else {
        let sub_size = product_of(&shape[1..]);
        for child in childs {
            match &**child {
                InitVal::Aggregate(grand_childs) => {
                    // An inner brace group fills the next complete sub-array;
                    // align the cursor to the sub-array boundary.
                    while filled % sub_size != 0 {
                        out.push(FlatElem::Const(0));
                        filled += 1;
                    }
                    flatten_aggregate(
                        &shape[1..],
                        grand_childs,
                        is_global,
                        program,
                        my_ir_generator_info,
                        out,
                    )?;
                    filled += sub_size;
                }
                InitVal::Exp(exp) => {
                    out.push(eval_init_exp(exp, is_global, program, my_ir_generator_info)?);
                    filled += 1;
                }
            }
        }
    }
    if filled > total {
        return Err("Too many elements in aggregate initializer".to_string());
    }
    while filled < total {
        out.push(FlatElem::Const(0));
        filled += 1;
    }
    Ok(())
}

/// Build the Koopa constant aggregate value tree from the flattened elements.
/// Dynamic elements are recorded in `dyn_elems` and set to 0 in the constant
/// aggregate; callers must overwrite them with per-element stores.
fn build_aggregate_tree(
    shape: &[usize],
    flat: &[FlatElem],
    cursor: &mut usize,
    program: &mut Program,
    dyn_elems: &mut Vec<(usize, Value)>,
) -> Result<Value, String> {
    if shape.len() <= 1 {
        let n = if shape.is_empty() { 1 } else { shape[0] };
        let mut elems = Vec::with_capacity(n);
        for _ in 0..n {
            match &flat[*cursor] {
                FlatElem::Const(int) => elems.push(program.new_value().integer(*int)),
                FlatElem::Dyn(value) => {
                    elems.push(program.new_value().integer(0));
                    dyn_elems.push((*cursor, *value));
                }
            }
            *cursor += 1;
        }
        if shape.is_empty() {
            // Scalar braces, e.g. `int a = {5};`.
            Ok(elems.pop().unwrap())
        } else {
            Ok(program.new_value().aggregate(elems))
        }
    } else {
        let mut elems = Vec::with_capacity(shape[0]);
        for _ in 0..shape[0] {
            elems.push(build_aggregate_tree(&shape[1..], flat, cursor, program, dyn_elems)?);
        }
        Ok(program.new_value().aggregate(elems))
    }
}

fn build_new_aggregate(
    shape: &[usize],
    childs: &[Box<InitVal>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    dyn_elems: &mut Vec<(usize, Value)>,
) -> Result<(Value, usize), String> {
    let mut flat = Vec::new();
    flatten_aggregate(shape, childs, is_global, program, my_ir_generator_info, &mut flat)?;
    let total = flat.len();
    let mut cursor = 0usize;
    let value = build_aggregate_tree(shape, &flat, &mut cursor, program, dyn_elems)?;
    Ok((value, total))
}

/// Store a constant aggregate value into a local array alloc slot
/// element-by-element with getelemptr/store chains.
fn aggregate_to_store_insts(
    aggr: Value,
    aggr_ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    let data = get_valuedata(aggr, program, my_ir_generator_info);
    match data.kind() {
        ValueKind::Integer(int) => {
            let value = create_new_local_value(program, my_ir_generator_info).integer(int.value());
            let store = create_new_local_value(program, my_ir_generator_info).store(value, aggr_ptr);
            insert_local_instructions(program, my_ir_generator_info, [value, store]);
            Ok(())
        }
        ValueKind::Aggregate(aggregate) => {
            let elems: Vec<Value> = aggregate.elems().to_vec();
            for (j, elem) in elems.into_iter().enumerate() {
                let index = create_new_local_value(program, my_ir_generator_info).integer(j as i32);
                let gep =
                    create_new_local_value(program, my_ir_generator_info).get_elem_ptr(aggr_ptr, index);
                insert_local_instructions(program, my_ir_generator_info, [index, gep]);
                aggregate_to_store_insts(elem, gep, program, my_ir_generator_info)?;
            }
            Ok(())
        }
        _ => Err(format!(
            "aggregate_to_store_insts: unexpected value kind: {:?}",
            data.kind()
        )),
    }
}

/// Emit per-element stores for the dynamic elements of a local aggregate
/// initializer, addressing them with getelemptr chains derived from the
/// flattened index (row-major).
fn emit_dyn_elem_stores(
    shape: &[usize],
    dyn_elems: &[(usize, Value)],
    alloc: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    for (flat_index, value) in dyn_elems {
        // Decompose the flattened index into per-dimension indices.
        let mut indices = Vec::with_capacity(shape.len());
        let mut rest = *flat_index;
        for i in 0..shape.len() {
            let stride = product_of(&shape[i + 1..]);
            indices.push(rest / stride);
            rest %= stride;
        }
        let mut ptr = alloc;
        for index in indices {
            let index_value =
                create_new_local_value(program, my_ir_generator_info).integer(index as i32);
            let gep = create_new_local_value(program, my_ir_generator_info)
                .get_elem_ptr(ptr, index_value);
            insert_local_instructions(program, my_ir_generator_info, [index_value, gep]);
            ptr = gep;
        }
        let store = create_new_local_value(program, my_ir_generator_info).store(*value, ptr);
        insert_local_instructions(program, my_ir_generator_info, [store]);
    }
    Ok(())
}

/// Extract the constant integer from a constant value, e.g. the result of
/// building a scalar aggregate initializer like `{5}`.
fn const_int_from_value(
    value: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<i32, String> {
    match get_valuedata(value, program, my_ir_generator_info).kind() {
        ValueKind::Integer(int) => Ok(int.value()),
        _ => Err(format!("Expected a constant integer value, got {:?}", value)),
    }
}

impl InitVal {
    fn build(
        &self,
        shape: &[usize],
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRInitValBuildResult, String> {
        let is_global = my_ir_generator_info.curr_func.is_none();
        match self {
            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
                IRExpBuildResult::Value(value) => {
                    if is_global {
                        Err(format!(
                            "Non-constant expression '{:?}' in global variable initval: {:?}",
                            exp, self
                        ))
                    } else {
                        Ok(IRInitValBuildResult::Var(value))
                    }
                }
            },
            InitVal::Aggregate(childs) => {
                let mut dyn_elems = Vec::new();
                let (value, _) = build_new_aggregate(
                    shape,
                    childs,
                    is_global,
                    program,
                    my_ir_generator_info,
                    &mut dyn_elems,
                )?;
                if dyn_elems.is_empty() {
                    Ok(IRInitValBuildResult::Aggregate(value))
                } else {
                    Ok(IRInitValBuildResult::AggregateWithDyn(value, dyn_elems))
                }
            }
        }
    }
}

impl IRBuildable for Decl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            Decl::ConstDecl(const_decl) => const_decl.build(program, my_ir_generator_info),
            Decl::VarDecl(var_decl) => var_decl.build(program, my_ir_generator_info),
        }
    }
}

/// Build the Koopa value(s) for a variable definition and insert it into the
/// current symbol table. Shared by `VarDecl::build` and by `ConstDecl::build`
/// for constant arrays.
fn build_var_def(
    btype: &BType,
    ident: &str,
    shape: &[usize],
    init_val: Option<&InitVal>,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    if my_ir_generator_info
        .symbol_tables
        .symbol_tables
        .last()
        .unwrap()
        .contains_key(ident)
    {
        return Err(format!("Duplicate symbol definition: {}", ident));
    }
    let is_global = my_ir_generator_info.curr_func.is_none();
    let type_kind = get_array_type(btype, shape);
    let ty = Type::get(type_kind.clone());
    let ptr = if shape.is_empty() {
        // Scalar.
        if is_global {
            let init = match init_val {
                None => program.new_value().zero_init(ty),
                Some(init_val) => match init_val.build(shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Const(int) => program.new_value().integer(int),
                    IRInitValBuildResult::Aggregate(value) => value,
                    _ => {
                        return Err(format!(
                            "Global variable '{}' must be initialized with a constant",
                            ident
                        ))
                    }
                },
            };
            program.new_value().global_alloc(init)
        } else {
            let alloc = create_new_local_value(program, my_ir_generator_info).alloc(ty);
            insert_local_instructions(program, my_ir_generator_info, [alloc]);
            if let Some(init_val) = init_val {
                match init_val.build(shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Const(int) => {
                        let value =
                            create_new_local_value(program, my_ir_generator_info).integer(int);
                        let store =
                            create_new_local_value(program, my_ir_generator_info).store(value, alloc);
                        insert_local_instructions(program, my_ir_generator_info, [value, store]);
                    }
                    IRInitValBuildResult::Var(value) => {
                        let store =
                            create_new_local_value(program, my_ir_generator_info).store(value, alloc);
                        insert_local_instructions(program, my_ir_generator_info, [store]);
                    }
                    IRInitValBuildResult::Aggregate(value) => {
                        // Scalar braces, e.g. `int a = {5};`.
                        let int = const_int_from_value(value, program, my_ir_generator_info)?;
                        let value =
                            create_new_local_value(program, my_ir_generator_info).integer(int);
                        let store =
                            create_new_local_value(program, my_ir_generator_info).store(value, alloc);
                        insert_local_instructions(program, my_ir_generator_info, [value, store]);
                    }
                    IRInitValBuildResult::AggregateWithDyn(_, dyn_elems) => {
                        // Scalar braces with a dynamic element, e.g. `int a = {b};`.
                        emit_dyn_elem_stores(
                            shape,
                            &dyn_elems,
                            alloc,
                            program,
                            my_ir_generator_info,
                        )?;
                    }
                }
            }
            alloc
        }
    } else {
        // Array.
        if is_global {
            let init = match init_val {
                None => program.new_value().zero_init(ty),
                Some(init_val) => match init_val.build(shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Aggregate(value) => value,
                    _ => {
                        return Err(format!(
                            "Global array '{}' must be initialized with a constant aggregate",
                            ident
                        ))
                    }
                },
            };
            program.new_value().global_alloc(init)
        } else {
            let alloc = create_new_local_value(program, my_ir_generator_info).alloc(ty);
            insert_local_instructions(program, my_ir_generator_info, [alloc]);
            if let Some(init_val) = init_val {
                match init_val.build(shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Aggregate(value) => {
                        aggregate_to_store_insts(value, alloc, program, my_ir_generator_info)?;
                    }
                    IRInitValBuildResult::AggregateWithDyn(value, dyn_elems) => {
                        aggregate_to_store_insts(value, alloc, program, my_ir_generator_info)?;
                        emit_dyn_elem_stores(
                            shape,
                            &dyn_elems,
                            alloc,
                            program,
                            my_ir_generator_info,
                        )?;
                    }
                    _ => {
                        return Err(format!(
                            "Array '{}' must be initialized with an aggregate",
                            ident
                        ))
                    }
                }
            }
            alloc
        }
    };
    my_ir_generator_info
        .symbol_tables
        .insert(ident.to_string(), SymbolTableEntry::Variable(type_kind, ptr));
    Ok(())
}

impl IRBuildable for ConstDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let ConstDecl::Default(btype, const_defs) = self;
        for ConstDef::Default(ident, shape_exps, init_val) in const_defs {
            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            if shape.is_empty() {
                // Scalar constant.
                if my_ir_generator_info
                    .symbol_tables
                    .symbol_tables
                    .last()
                    .unwrap()
                    .contains_key(&ident.content)
                {
                    return Err(format!("Duplicate symbol definition: {}", ident.content));
                }
                let int = match init_val.build(&shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Const(int) => int,
                    IRInitValBuildResult::Aggregate(value) => {
                        const_int_from_value(value, program, my_ir_generator_info)?
                    }
                    _ => {
                        return Err(format!(
                            "Const '{}' must be initialized with a constant expression",
                            ident.content
                        ))
                    }
                };
                my_ir_generator_info.symbol_tables.insert(
                    ident.content.clone(),
                    SymbolTableEntry::Constant(btype.content.clone(), int),
                );
            } else {
                // Constant arrays are stored in memory like variables.
                build_var_def(
                    btype,
                    &ident.content,
                    &shape,
                    Some(init_val),
                    program,
                    my_ir_generator_info,
                )?;
            }
        }
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for VarDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let VarDecl::Default(btype, var_defs) = self;
        for VarDef::Default(ident, shape_exps, init_val) in var_defs {
            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            build_var_def(
                btype,
                &ident.content,
                &shape,
                init_val.as_ref(),
                program,
                my_ir_generator_info,
            )?;
        }
        Ok(IRBuildResult::OK)
    }
}
